'use strict';
const U=[-1,-.5,0,.5,1], colors=['#9760bf','#277eb7','#158b79','#d18a25','#ce5865'];
const $=id=>document.getElementById(id), mean=a=>a.reduce((x,y)=>x+y,0)/a.length;
function errors(a,b){return U.map(u=>.8+1.4*u+.22*(u*u-.5)+a+b*u)}
function rms(r){return Math.sqrt(mean(r.map(x=>x*x)))}
function solve(a,b,scalar=false){const r=errors(a,b),ra=mean(r),rb=mean(r.map((v,i)=>v*U[i])),lambda=.1;
 if(scalar){const norm=rms(r);if(norm<1e-12)return [0,0];const g=[ra/norm,rb/norm],den=g[0]**2+g[1]**2+lambda;return g.map(x=>-norm*x/den)}
 return [-ra/(1+lambda),-rb/(mean(U.map(x=>x*x))+lambda)];}
let a=0,b=0,stage=0,selected=-1,busy=false,frame=0,previous=null;
const steps=[['Move one parameter. Watch every ray.','Drag A to shift the whole bundle. Drag B to change the spread. Each slider changes one shared parameter—not one ray.'],['The Jacobian is a map of shared effects.','A column answers: “What does this parameter do to all five rays?” The rows keep those different responses visible.'],['LM combines the two patterns into one update.','The solver predicts all five ray errors at once, then chooses one ΔA and one ΔB to reduce their squared sum.']];
function fmt(n){return (n>=0?'+':'−')+Math.abs(n).toFixed(2)}
function draw(){const r=errors(a,b),y=v=>200-v*38,target=200,x0=66,xm=277,xd=530;
 let s=`<rect x="503" y="29" width="54" height="341" rx="12" fill="#edf1e8"/><line x1="${xd}" y1="38" x2="${xd}" y2="361" stroke="#839789" stroke-width="2"/><text x="44" y="20" fill="#607377" font-size="11" font-family="monospace">PUPIL SAMPLES</text><text x="247" y="20" fill="#607377" font-size="11" font-family="monospace">SHARED OPTICS</text><text x="505" y="20" fill="#607377" font-size="11" font-family="monospace">DETECTOR</text><path d="M 280 50 Q 240 200 280 350" stroke="#a1b4a4" stroke-width="9" fill="none"/><line x1="300" y1="200" x2="685" y2="200" stroke="#9cae98" stroke-dasharray="4 5"/><circle cx="${xd}" cy="200" r="11" fill="#d5ec8c" stroke="#176b54"/><text x="567" y="194" fill="#176b54" font-size="12">target: 0</text>`;
 for(let i=0;i<5;i++){const start=200-U[i]*132,end=y(r[i]),op=selected<0||selected===i?1:.17;
 s+=`<g opacity="${op}"><path d="M ${x0} ${start} L ${xm-10} ${start} L ${xd} ${end}" stroke="${colors[i]}" stroke-width="${selected===i?3.5:2}" fill="none"/><circle cx="${x0}" cy="${start}" r="5" fill="${colors[i]}"/><text x="29" y="${start+4}" fill="${colors[i]}" font-size="12" font-weight="600">${'ABCDE'[i]}</text><circle cx="${xd}" cy="${end}" r="6" fill="${colors[i]}" stroke="white" stroke-width="2"/></g>`;
 if(previous){const old=y(previous[i]);s+=`<circle cx="${xd+14}" cy="${old}" r="3" fill="none" stroke="${colors[i]}" opacity=".45"/><line x1="${xd+14}" y1="${old}" x2="${xd+14}" y2="${end}" stroke="${colors[i]}" opacity=".4"/>`}}
 s+='<text x="42" y="394" fill="#607377" font-size="11">Different ray movements can come from the same shared adjustment.</text>';$('scene').innerHTML=s;
 $('a').value=a;$('b').value=b;$('av').textContent=fmt(a);$('bv').textContent=fmt(b);$('rms').textContent=rms(r).toFixed(3);
 $('matrix').innerHTML=r.map((v,i)=>`<tr class="${selected===i?'active':''}" data-ray="${i}" tabindex="0" aria-label="Highlight ray ${'ABCDE'[i]}"><td><span class="dot" style="background:${colors[i]}"></span>${'ABCDE'[i]}</td><td>${fmt(v)}</td><td><span class="pill">+1.00</span></td><td><span class="pill">${fmt(U[i])}</span></td></tr>`).join('');
 const [da,db]=solve(a,b);$('da').textContent=fmt(da);$('db').textContent=fmt(db);$('prediction').textContent=`Predicted RMS: ${rms(r).toFixed(3)} → ${rms(errors(a+da,b+db)).toFixed(3)}. One update, shared by all rays.`;
}
function setStage(n){stage=n;document.querySelectorAll('[data-stage]').forEach((el,i)=>{if(i===n)el.setAttribute('aria-current','step');else el.removeAttribute('aria-current')});$('heading').textContent=steps[n][0];$('intro').textContent=steps[n][1];$('explanation').hidden=n===0;$('stepbox').hidden=n!==2;$('advance').textContent=n===0?'Next: see the Jacobian →':n===1?'Next: take an LM step →':'Animate one LM step →';$('controlnote').textContent=n===2?'Damping λ = 0.10. The small remaining error cannot be removed with these two controls.':'Try A first, then B. Watch all the ray endpoints.';$('righttitle').textContent=n===2?'One solve. Two shared adjustments.':'Separate measurements. Shared controls.';$('righttext').textContent=n===2?'LM uses every row together. It balances conflicting ray responses rather than changing rays independently.':'For a small change, each row predicts its ray’s movement. The very same ΔA and ΔB appear in every row.';draw()}
function cancel(){cancelAnimationFrame(frame);busy=false;$('a').disabled=false;$('b').disabled=false;$('advance').disabled=false;$('scalar').disabled=false;}
function animate(scalar){if(busy)return;const oa=a,ob=b,[da,db]=solve(a,b,scalar),before=rms(errors(a,b));if(a+da < -2||a+da > 2||b+db < -2.5||b+db > 2.5){$('status').textContent='This step exceeds the demo slider range. Reset to compare the two methods.';return}previous=errors(a,b);const start=performance.now();busy=true;['a','b','advance','scalar'].forEach(id=>$(id).disabled=true);const full=solve(a,b),alternative=rms(errors(a+full[0],b+full[1]));
 function tick(now){let t=Math.min(1,(now-start)/1100),ease=t*t*(3-2*t);a=oa+da*ease;b=ob+db*ease;draw();if(t<1){frame=requestAnimationFrame(tick)}else{cancel();$('status').textContent=scalar?`One RMS residual: ${before.toFixed(3)} → ${rms(errors(a,b)).toFixed(3)}. From that same start, per-ray LM would reach ${alternative.toFixed(3)}. Same objective; different step geometry.`:`LM changed A by ${fmt(da)} and B by ${fmt(db)}. All five rays moved. RMS: ${before.toFixed(3)} → ${rms(errors(a,b)).toFixed(3)}.`}}
 frame=requestAnimationFrame(tick)}
['a','b'].forEach(id=>$(id).addEventListener('input',()=>{cancel();a=+$('a').value;b=+$('b').value;previous=null;draw();$('status').textContent=id==='a'?'A moves every ray together. Five responses, one shared control.':'B moves the outer rays oppositely; the center ray stays put. One shared control, different responses.'}));
$('reset').onclick=()=>{cancel();a=b=0;selected=-1;previous=null;draw();$('status').textContent='Starting design restored. Try A, try B, or animate an LM step.'};
$('advance').onclick=()=>stage<2?setStage(stage+1):animate(false);$('scalar').onclick=()=>animate(true);
document.querySelectorAll('[data-stage]').forEach(el=>el.onclick=()=>setStage(+el.dataset.stage));
function selectRow(e){const row=e.target.closest('[data-ray]');if(!row)return;const id=+row.dataset.ray;selected=selected===id?-1:id;draw()}
$('matrix').onclick=selectRow;$('matrix').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectRow(e)}};setStage(0);
